import { StudioProApi } from "@mendix/extensions-api";
import { ModelDocument } from "../types/modelDocument";
import {
    getConstantById,
    getConstantDefaultValue,
    getRuntimeConstantByQualifiedName,
    isStringConstant,
} from "./constantUtils";

export const ConstantValidationErrors = {
    EmptyValue: "EmptyValue",
    Excluded: "Excluded",
    InvalidType: "InvalidType",
    NotFound: "NotFound",
    PrivateValue: "PrivateValue",
    Required: "Required",
} as const;

export type ConstantValidationError = (typeof ConstantValidationErrors)[keyof typeof ConstantValidationErrors];

/**
 * Reusable validation function for string constants.
 *
 * This function validates that:
 * - The constant name is provided
 * - The constant exists in the project
 * - The constant is of type string
 * - The constant has a public runtime value (if configured)
 * - The constant has either a default value or runtime value set
 *
 * @param fieldName - The name of the field being validated
 * @returns A validation error message if validation fails, otherwise undefined
 */
export const validateStringConstant = async (
    studioPro: StudioProApi,
    modelDocument?: ModelDocument
): Promise<ConstantValidationError | undefined> => {
    if (!modelDocument) {
        return ConstantValidationErrors.Required;
    }

    const constant = await getConstantById(studioPro, modelDocument.documentId);

    if (!constant) {
        return ConstantValidationErrors.NotFound;
    }

    if (constant.excluded) {
        return ConstantValidationErrors.Excluded;
    }

    if (!isStringConstant(constant)) {
        return ConstantValidationErrors.InvalidType;
    }

    const runTimeConstant = await getRuntimeConstantByQualifiedName(studioPro, modelDocument.qualifiedName);

    if (runTimeConstant?.status === "private") {
        return ConstantValidationErrors.PrivateValue;
    }

    const runtimeValue = runTimeConstant?.value;
    const defaultValue = getConstantDefaultValue(constant);

    if (!defaultValue && !runtimeValue) {
        return ConstantValidationErrors.EmptyValue;
    }

    return undefined;
};
